def test_build_query(add_languages):
    rec = {
        'title': 'magic',
        'languages': ['eng', 'fre'],
        'translated_from': ['yid'],
        'authors': [{'name': 'Surname, Forename'}],
        'description': 'test',
    }
    q = build_query(rec)
    assert q['title'] == 'magic'
    assert q['authors'][0]['name'] == 'Forename Surname'
    assert q['description'] == {'type': '/type/text', 'value': 'test'}
